const rows = $input.all().map(i => i.json);
// Closing sentence starts with the stable template phrase and ends at the first "fundraising round."
const stripRe = /\s*If the opportunity fits[\s\S]*?fundraising round\.\s*/i;
const closeRe = /investment mandate|arrange a discussion|happy to arrange/i;

const results = [];
let matched = 0, unmatched = 0;
for (const r of rows) {
  const memo = String(r.memo_html || '');
  const name = r.startup || r.startup_name || '(unknown)';
  if (!closeRe.test(memo)) continue; // only the 16 flagged
  const m = memo.match(stripRe);
  if (m) {
    matched++;
    const idx = m.index;
    const stripped = memo.replace(stripRe, ' ');
    results.push({
      row_number: r.row_number,
      startup: name,
      status: 'WILL_STRIP',
      removing: m[0].trim(),
      before_tail: memo.slice(Math.max(0, idx - 80), idx + m[0].length + 20),
      after_tail: stripped.slice(Math.max(0, idx - 100)),
      new_len: stripped.length,
      old_len: memo.length,
      still_has_closing_after: closeRe.test(stripped),
    });
  } else {
    unmatched++;
    // show tail so we can craft a rule for these
    results.push({
      row_number: r.row_number,
      startup: name,
      status: 'NO_MATCH_NEEDS_REVIEW',
      tail: memo.slice(-400),
    });
  }
}
return [{ json: { total_flagged: results.length, will_strip: matched, needs_review: unmatched, results } }];
